import {cornerSettings,KERB_MODES} from './corner-settings.js?v=20261007-safety';
import {buildGeometry} from './engine.js?v=20261007-safety';
const $=s=>document.querySelector(s);
const PRESETS={balanced:{rounding:1,entryStrength:1,exitStrength:1},late:{rounding:.85,entryStrength:.6,exitStrength:1.4},early:{rounding:.85,entryStrength:1.4,exitStrength:.6},hairpin:{rounding:.35,entryStrength:.65,exitStrength:.65},sweeper:{rounding:1,entryStrength:1.5,exitStrength:1.5}};
export function mountCorners(api){
  const panel=document.createElement('section');panel.className='panel-section corner-panel';
  panel.innerHTML=`<div class="section-heading"><span class="section-num">TURN</span><h2>Corner workshop</h2><span id="corner-number" class="scene-tag"></span></div><p id="corner-empty" class="field-hint">Shift-click road handles to select several, or choose one point below.</p><div class="corner-navigation"><button id="previous-corner" class="outline-button" aria-label="Previous corner point">←</button><select id="corner-select" aria-label="Choose corner control point"></select><button id="next-corner" class="outline-button" aria-label="Next corner point">→</button></div><p id="corner-selection-note" class="field-hint" role="status"></p><div id="corner-controls" hidden><label class="studio-field">Corner name<input id="corner-name" maxlength="40" placeholder="e.g. Sunset hairpin"></label><div class="corner-profile" id="corner-profile"></div><div class="corner-metrics" id="corner-metrics"></div><p class="field-hint">Curve presets shape the approach and departure. The orange dot is your control point.</p><div class="corner-presets" role="group" aria-label="Corner curve presets"><button data-corner-preset="balanced">Balanced</button><button data-corner-preset="late">Long exit</button><button data-corner-preset="early">Long entry</button><button data-corner-preset="hairpin">Tight bend</button><button data-corner-preset="sweeper">Sweeper</button></div><div class="corner-shapes" role="group" aria-label="Corner shape"><button data-rounding="0">Sharp</button><button data-rounding=".35">Tight</button><button data-rounding="1">Rounded</button></div><label class="studio-field">Rounding <output id="rounding-value"></output><input id="corner-rounding" type="range" min="0" max="100" step="1"></label><label class="studio-field">Entry reach <output id="entry-value"></output><input id="corner-entry" type="range" min="0" max="160" step="5"></label><label class="studio-field">Exit reach <output id="exit-value"></output><input id="corner-exit" type="range" min="0" max="160" step="5"></label><p class="field-hint">100% keeps the original curve. Increase reach for a wider sweep; reduce it for a tighter approach. Neighboring sections also change.</p><div class="studio-fields"><label class="studio-field">Kerbs<select id="corner-kerbs">${Object.entries(KERB_MODES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="studio-field">Kerb width · m<input id="corner-kerb-width" type="number" min=".25" max="2" step=".05"></label><label class="studio-field">Banking · degrees<input id="corner-banking" type="number" min="-15" max="15" step=".5"></label><label class="studio-field">Elevation · m<input id="corner-elevation" type="number" min="-100" max="500" step=".1"></label></div><div class="corner-copy-actions"><button id="copy-corner" class="outline-button">Copy style</button><button id="paste-corner" class="outline-button" disabled>Paste style</button></div><button id="reset-corner" class="outline-button">Reset curve & banking</button><p id="corner-hint" class="field-hint"></p></div>`;
  $('.point-section').after(panel);let lastPoints='',copied=null;
  const select=index=>{const t=api.getTrack();if(t.points.length)api.selectPoint((index+t.points.length)%t.points.length);};
  $('#corner-select').onchange=()=>select(Number($('#corner-select').value));$('#previous-corner').onclick=()=>select(Math.max(0,api.getSelected())-1);$('#next-corner').onclick=()=>select(api.getSelected()+1);
  const change=(key,value)=>{const i=api.getSelected();if(i<0)return;api.updateSelectedPoints(p=>p[key]=value);};
  $('#corner-name').onchange=()=>change('cornerName',$('#corner-name').value.trim());
  panel.querySelectorAll('[data-rounding]').forEach(b=>b.onclick=()=>change('rounding',Number(b.dataset.rounding)));
  panel.querySelectorAll('[data-corner-preset]').forEach(b=>b.onclick=()=>{const i=api.getSelected();if(i<0)return;api.updateSelectedPoints((p,i,t)=>{t.smooth=true;Object.assign(p,PRESETS[b.dataset.cornerPreset]);});});
  for(const [id,key,out] of [['rounding','rounding','rounding'],['entry','entryStrength','entry'],['exit','exitStrength','exit']]){
    $('#corner-'+id).oninput=()=>{const value=Number($('#corner-'+id).value)/100;$('#'+out+'-value').textContent=`${Math.round(value*100)}%`;const t=api.getTrack(),i=api.getSelected();if(i>=0)drawPreview(t,i,{[key]:value});};
    $('#corner-'+id).onchange=()=>change(key,Number($('#corner-'+id).value)/100);
  }
  $('#corner-kerbs').onchange=()=>change('kerbs',$('#corner-kerbs').value);
  for(const [id,key,min,max] of [['corner-kerb-width','kerbWidth',.25,2],['corner-banking','bank',-15,15],['corner-elevation','elevation',-100,500]])$('#'+id).onchange=()=>{const v=Number($('#'+id).value);if(!Number.isFinite(v)||v<min||v>max){api.toast(`Enter a value between ${min} and ${max}.`);refresh();return;}change(key,v);};
  $('#copy-corner').onclick=()=>{const p=api.getTrack().points[api.getSelected()];if(!p)return;const {cornerName,...style}=cornerSettings(p);copied={...style,bank:p.bank||0};refresh();api.toast('Corner style copied. Choose another point and paste.');};
  $('#paste-corner').onclick=()=>{const i=api.getSelected();if(copied&&i>=0)api.updateSelectedPoints(p=>Object.assign(p,copied));};
  $('#reset-corner').onclick=()=>{const i=api.getSelected();if(i>=0)api.updateSelectedPoints(p=>{const name=p.cornerName;Object.assign(p,cornerSettings(),{cornerName:name,bank:0});});};
  function drawPreview(t,i,override={}){
    const selected=new Set(api.getSelectedPoints()),points=t.points.map((p,j)=>selected.has(j)?{...p,...override}:p),g=buildGeometry(points,t.smooth,t.complete!==false),n=points.length,previous=(i+n-1)%n;
    const curve=g.samples.filter((_,j)=>g.segments[j]===previous||g.segments[j]===i),p=points[i];
    if(!curve.length)curve.push(p);
    const minX=Math.min(...curve.map(p=>p.x)),maxX=Math.max(...curve.map(p=>p.x)),minY=Math.min(...curve.map(p=>p.y)),maxY=Math.max(...curve.map(p=>p.y));
    const s=Math.min(230/Math.max(1,maxX-minX),110/Math.max(1,maxY-minY));const xy=p=>[135+(p.x-(minX+maxX)/2)*s,75+(p.y-(minY+maxY)/2)*s];
    const paths=[previous,i].map(segment=>{const list=g.samples.filter((_,j)=>g.segments[j]===segment);if(list.length)list.push(points[(segment+1)%n]);return list.map((p,j)=>`${j?'L':'M'}${xy(p).map(v=>v.toFixed(2)).join(' ')}`).join('');});
    $('#corner-profile').innerHTML=`<svg viewBox="0 0 270 150" role="img" aria-label="Actual entry and exit curve around the selected point">${paths.map(d=>`<path d="${d}" fill="none" stroke="#364d44" stroke-width="12" stroke-linejoin="round" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#efe8d3" stroke-width="1.2" stroke-dasharray="4 5"/>`).join('')}<circle cx="${xy(p)[0]}" cy="${xy(p)[1]}" r="5" fill="#dc8553" stroke="#fff4df" stroke-width="2"/></svg>`;
    const before=points[t.complete!==false?previous:Math.max(0,i-1)],after=points[t.complete!==false?(i+1)%n:Math.min(n-1,i+1)];
    const a=Math.atan2(p.y-before.y,p.x-before.x),b=Math.atan2(after.y-p.y,after.x-p.x),angle=Math.atan2(Math.sin(b-a),Math.cos(b-a))*180/Math.PI;
    $('#corner-metrics').textContent=(i===0||i===n-1)&&t.complete===false?'Open road endpoint':`${angle<0?'Left':'Right'} turn · ${Math.round(Math.abs(angle))}° control-point deflection`;
  }
  function refresh(){
    const t=api.getTrack(),i=api.getSelected(),p=t.points[i],key=JSON.stringify(t.points.map(p=>p.cornerName||''));
    const selected=api.getSelectedPoints();$('#corner-selection-note').textContent=selected.length>1?`${selected.length} road points selected. Values shown are from active point ${i+1}; changing a field applies it to every selected point. Drag any selected handle to move the group. Escape clears the selection.`:'Shift-click road handles in Move to select multiple points. All corner controls apply to the selection.';
    $('#previous-corner').disabled=$('#next-corner').disabled=!t.points.length;$('#corner-select').disabled=!t.points.length;
    if(key!==lastPoints){lastPoints=key;$('#corner-select').replaceChildren();const placeholder=new Option('Choose a road point','-1');placeholder.disabled=true;$('#corner-select').append(placeholder);t.points.forEach((p,j)=>$('#corner-select').append(new Option(`${String(j+1).padStart(2,'0')} · ${p.cornerName||'Road point'}`,String(j))));}
    $('#corner-select').value=String(p?i:-1);$('#corner-controls').hidden=!p;$('#corner-empty').hidden=!!p;$('#corner-number').textContent=p?`POINT ${i+1}`:'';if(!p)return;
    const c=cornerSettings(p);$('#corner-name').value=c.cornerName;
    for(const [id,key,out] of [['rounding','rounding','rounding'],['entry','entryStrength','entry'],['exit','exitStrength','exit']]){$('#corner-'+id).value=Math.round(c[key]*100);$('#'+out+'-value').textContent=`${Math.round(c[key]*100)}%`;}
    $('#corner-kerbs').value=c.kerbs;$('#corner-kerb-width').value=c.kerbWidth;$('#corner-banking').value=p.bank||0;$('#corner-elevation').value=p.elevation||0;$('#paste-corner').disabled=!copied;
    panel.querySelectorAll('[data-rounding]').forEach(b=>b.classList.toggle('active',Math.abs(Number(b.dataset.rounding)-c.rounding)<.01));
    panel.querySelectorAll('[data-corner-preset]').forEach(b=>b.setAttribute('aria-pressed',String(Object.entries(PRESETS[b.dataset.cornerPreset]).every(([key,v])=>Math.abs(c[key]-v)<.01))));
    drawPreview(t,i);$('#corner-hint').textContent=(t.smooth?'Changes appear in the editor, 3D preview, and exported mod. ':'Enable Smooth corners in Design to use curve shaping. ')+(t.export?.kerbs===false?'Enable kerbs in Export to include your kerb settings.':'Kerbs apply to the outgoing section.');
  }
  return {refresh};
}
